-- Resolved once during module preparation, before enable-time patches.
-- UCP owns scanning, caching and operand extraction. No image allowlist.
local M={}
function M.resolve(core,utils,game,ffi)
  local function pointer(value) return ffi.tonumber(ffi.cast('unsigned long',value)) end
  -- These bindings already belong to the UI dependency; consume its exports.
  local addresses={mouseState=pointer(game.Input.mouseState),
    mouseInsideBox=pointer(game.Input.isMouseInsideBox),
    buttonSurface=pointer(game.Rendering.alphaAndButtonSurface)}
  local function scan(name,pattern,capture)
    if capture then
      local _,value=utils.AOBExtractUnique(pattern,'custom-hotkeys.'..name)
      addresses[name]=value
    else addresses[name]=core.AOBScanUnique(pattern,'custom-hotkeys.'..name) end
  end
